  it.each([
    0,
    -1,
    NaN,
    Infinity,
    1.5,
    true,
    false,
    "",
    "1e3",
    "1.5",
    "secret-marker",
    Number.MAX_SAFE_INTEGER + 1,
  ])("rejects an invalid explicit output cap: %s", (maxOutputTokens) => {
