/**
 * verify-19 — 取消审批迟到回调 (cancel approval late callbacks).
 *
 * Independent regression coverage for the interactive-approval round-trip in
 * headless-stream.js: an approval request blocks the tool until a verdict
 * arrives, and the resolution path (`settleApproval`) must not let a late or
 * mis-routed verdict authorize anything:
 *   - a verdict that arrives after the request was already settled (deny,
 *     timeout, mismatch, …) targets a pending entry that no longer exists, so
 *     it is discarded (`if (!p) return;`) and cannot green-light a new request;
 *   - a normal accept is accepted only when its approval binding matches the
 *     one the request advertised — an approve carrying a foreign binding (or a
 *     structured approve with no binding) is rejected as binding-mismatch /
 *     binding-missing and the tool stays declined.
 */
import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { PassThrough } from "node:stream";
import {
  runAgentHeadlessStream,
  parseInputEvent,
} from "../src/runtime/headless-stream.js";
import { approvalBindingDigest } from "../src/lib/agent-authority.js";

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// The fake loop hits a confirm-tier decision and reports the verdict it got
// back from the interactive permission gate in its reply content.
async function* confirmingLoop(messages, opts) {
  const lastUser = [...messages].reverse().find((m) => m.role === "user");
  if (/RISKY/.test(lastUser.content)) {
    const ok = await opts.permissionConfirm({
      tool: "run_shell",
      command: "npm run test:unit",
      riskLevel: "medium",
      reason: "settings rule asks",
    });
    yield { type: "response-complete", content: ok ? "executed" : "skipped (denied)" };
  } else {
    yield { type: "response-complete", content: "plain reply" };
  }
  yield { type: "run-ended", reason: "complete" };
}

function harness({ inputGen, agentLoop = confirmingLoop, options = {} }) {
  const lines = [];
  const deps = {
    bootstrap: async () => ({ db: null }),
    getApprovalGate: async () => null,
    writeOut: (s) => lines.push(s),
    writeErr: () => {},
    agentLoop,
    input: inputGen(),
  };
  return {
    run: () =>
      runAgentHeadlessStream(
        { expandFileRefs: false, interactiveApprovals: true, ...options },
        deps,
      ),
    events: () =>
      lines
        .join("")
        .trimEnd()
        .split("\n")
        .map((l) => JSON.parse(l)),
  };
}

describe("verify-19: cancel approval late callbacks", () => {
  beforeEach(() => {
    process.env.CC_APPROVAL_TIMEOUT_MS = "30000";
  });
  afterEach(() => {
    delete process.env.CC_APPROVAL_TIMEOUT_MS;
  });

  it("normal accept binds only the original request", async () => {
    const h = harness({
      inputGen: async function* () {
        yield JSON.stringify({ type: "user", text: "do the RISKY thing" }) + "\n";
        await sleep(80);
        yield JSON.stringify({ type: "approval", id: "appr-1", approve: true }) + "\n";
      },
    });
    await h.run();
    const req = h.events().find((e) => e.type === "approval_request");
    expect(req).toMatchObject({ id: "appr-1", tool: "run_shell", command: "npm run test:unit" });
    expect(h.events().find((e) => e.type === "approval_resolved")).toMatchObject({
      id: "appr-1",
      approved: true,
      via: "user-approve",
    });
    // only one approval_request and one resolution — the accept did not leak
    // an authorizing grant to any other request
    expect(h.events().filter((e) => e.type === "approval_request")).toHaveLength(1);
    expect(h.events().filter((e) => e.type === "approval_resolved")).toHaveLength(1);
  });

  it("a late approve after the request was already declined cannot authorize", async () => {
    const h = harness({
      inputGen: async function* () {
        yield JSON.stringify({ type: "user", text: "do the RISKY thing" }) + "\n";
        await sleep(80); // let the turn reach the confirm
        // decline first, then (late) try to approve the same request id
        yield JSON.stringify({ type: "approval", id: "appr-1", approve: false }) + "\n";
        await sleep(60);
        yield JSON.stringify({ type: "approval", id: "appr-1", approve: true }) + "\n";
      },
    });
    await h.run();
    const resolved = h.events().filter((e) => e.type === "approval_resolved");
    // exactly one resolution, for the decline; the late approve is discarded
    expect(resolved).toHaveLength(1);
    expect(resolved[0]).toMatchObject({ id: "appr-1", approved: false });
    expect(h.events().find((e) => e.type === "result").result).toBe("skipped (denied)");
  });

  it("an approve carrying a mismatched binding cannot authorize a different call", async () => {
    const foreign = approvalBindingDigest({
      toolCallId: "appr-other",
      args: { command: "rm -rf /" },
      policyDigest: "high",
    });
    const h = harness({
      inputGen: async function* () {
        yield JSON.stringify({ type: "user", text: "do the RISKY thing" }) + "\n";
        await sleep(80);
        yield JSON.stringify({
          type: "approval",
          id: "appr-1",
          approve: true,
          binding: foreign,
        }) + "\n";
      },
    });
    await h.run();
    expect(h.events().find((e) => e.type === "approval_resolved")).toMatchObject({
      id: "appr-1",
      approved: false,
      via: "binding-mismatch",
    });
    expect(h.events().find((e) => e.type === "result").result).toBe("skipped (denied)");
  });

  it("a structured approve without its advertised binding is rejected (binding-missing)", async () => {
    const h = harness({
      inputGen: async function* () {
        yield JSON.stringify({ type: "user", text: "do the RISKY thing" }) + "\n";
        await sleep(80);
        yield JSON.stringify({
          type: "approval",
          id: "appr-1",
          approve: true,
          decision: { kind: "acceptOnce" },
        }) + "\n";
      },
    });
    await h.run();
    expect(h.events().find((e) => e.type === "approval_resolved")).toMatchObject({
      id: "appr-1",
      approved: false,
      via: "binding-missing",
    });
    expect(h.events().find((e) => e.type === "result").result).toBe("skipped (denied)");
  });

  it("a structured accept with the matching binding authorizes the original request", async () => {
    // capture the advertised binding from the emitted request, then echo it
    // back verbatim on the accept — a normal, correctly-bound accept works.
    const captured = new PassThrough();
    const events = [];
    const input = new PassThrough();
    input.write(JSON.stringify({ type: "user", text: "do the RISKY thing" }) + "\n");
    const outcome = runAgentHeadlessStream(
      { expandFileRefs: false, interactiveApprovals: true },
      {
        bootstrap: async () => ({ db: null }),
        getApprovalGate: async () => null,
        writeOut(line) {
          const event = JSON.parse(line);
          events.push(event);
          if (event.type === "approval_request") {
            queueMicrotask(() =>
              input.write(
                JSON.stringify({
                  type: "approval",
                  id: event.id,
                  approve: true,
                  decision: { kind: "acceptForTurn" },
                  binding: event.binding,
                }) + "\n",
              ),
            );
          }
        },
        writeErr: () => {},
        agentLoop: confirmingLoop,
        input,
      },
    );
    await outcome;
    const req = events.find((e) => e.type === "approval_request");
    expect(req.binding).toBeTruthy();
    const resolved = events.find((e) => e.type === "approval_resolved");
    expect(resolved).toMatchObject({ id: req.id, approved: true, via: "user-approve" });
    expect(events.find((e) => e.type === "result").result).toBe("executed");
    void captured;
  });
});

