        yield JSON.stringify({ type: "user", text: "do the RISKY thing" }) + "\n";
        await sleep(80); // let the turn reach the confirm
        // decline first, then (late) try to approve the same request id
        yield JSON.stringify({ type: "approval", id: "appr-1", approve: false }) + "\n";
        await sleep(60);
        yield JSON.stringify({ type: "approval", id: "appr-1", approve: true }) + "\n";
      },
    });
    await h.run();
    const resolved = h.events().filter((e) => e.type === "approval_resolved");
    // exactly one resolution, for the decline; the late approve is discarded
    expect(resolved).toHaveLength(1);
    expect(resolved[0]).toMatchObject({ id: "appr-1", approved: false });
    expect(h.events().find((e) => e.type === "result").result).toBe("skipped (denied)");
  });

  it("an approve carrying a mismatched binding cannot authorize a different call", async () => {
    const foreign = approvalBindingDigest({
      toolCallId: "appr-other",
      args: { command: "rm -rf /" },
      policyDigest: "high",
    });
    const h = harness({
      inputGen: async function* () {
        yield JSON.stringify({ type: "user", text: "do the RISKY thing" }) + "\n";
        await sleep(80);
        yield JSON.stringify({
          type: "approval",
          id: "appr-1",
          approve: true,
          binding: foreign,
        }) + "\n";
      },
    });
    await h.run();
    expect(h.events().find((e) => e.type === "approval_resolved")).toMatchObject({
      id: "appr-1",
      approved: false,
      via: "binding-mismatch",
    });
    expect(h.events().find((e) => e.type === "result").result).toBe("skipped (denied)");
  });

  it("a structured approve without its advertised binding is rejected (binding-missing)", async () => {
    const h = harness({
      inputGen: async function* () {
        yield JSON.stringify({ type: "user", text: "do the RISKY thing" }) + "\n";
        await sleep(80);
        yield JSON.stringify({
          type: "approval",
          id: "appr-1",
          approve: true,
          decision: { kind: "acceptOnce" },
        }) + "\n";
      },
    });
    await h.run();
    expect(h.events().find((e) => e.type === "approval_resolved")).toMatchObject({
      id: "appr-1",
      approved: false,
      via: "binding-missing",
    });
    expect(h.events().find((e) => e.type === "result").result).toBe("skipped (denied)");
  });

  it("a structured accept with the matching binding authorizes the original request", async () => {
    // capture the advertised binding from the emitted request, then echo it
    // back verbatim on the accept — a normal, correctly-bound accept works.
    const captured = new PassThrough();
    const events = [];
    const input = new PassThrough();
    input.write(JSON.stringify({ type: "user", text: "do the RISKY thing" }) + "\n");
    const outcome = runAgentHeadlessStream(
      { expandFileRefs: false, interactiveApprovals: true },
      {
        bootstrap: async () => ({ db: null }),
        getApprovalGate: async () => null,
        writeOut(line) {
          const event = JSON.parse(line);
          events.push(event);
          if (event.type === "approval_request") {
            queueMicrotask(() =>
              input.write(
                JSON.stringify({
                  type: "approval",
                  id: event.id,
                  approve: true,
                  decision: { kind: "acceptForTurn" },
                  binding: event.binding,
                }) + "\n",
              ),
            );
          }
        },
        writeErr: () => {},
        agentLoop: confirmingLoop,
        input,
      },
    );
    await outcome;
    const req = events.find((e) => e.type === "approval_request");
    expect(req.binding).toBeTruthy();
    const resolved = events.find((e) => e.type === "approval_resolved");
    expect(resolved).toMatchObject({ id: req.id, approved: true, via: "user-approve" });
    expect(events.find((e) => e.type === "result").result).toBe("executed");
    void captured;
  });
});

