  ...q,
  fields: values,
  revision: 1,
  ...extra,
});
function controller(store, overrides = {}) {
  cleanups.push(async () => {
    let queue;
    do {
      queue = store.queue;
      await queue;
    } while (queue !== store.queue);
  });
  const conv = {
    id: "a",
    sessionId: "session-1",
    draftKey: randomUUID(),
    _sessionToken: {},
    session: { running: true, sendEvent: vi.fn(() => true) },
